import re
from collections import defaultdict
from typing import Any

import httpx

from data_loader import get_line, get_station, public_station
from models import ArrivalBoardResponse, ArrivalEntry, DirectionBoard


TFL_ARRIVALS_URL = "https://api.tfl.gov.uk/Line/{line_id}/Arrivals/"
BOARD_DIRECTIONS = ("Northbound", "Eastbound", "Southbound", "Westbound")
PLATFORM_RE = re.compile(r"platform\s+([0-9A-Za-z]+)", re.IGNORECASE)


async def fetch_line_arrivals(line_id: str) -> list[dict[str, Any]]:
    async with httpx.AsyncClient(timeout=12.0) as client:
        response = await client.get(TFL_ARRIVALS_URL.format(line_id=line_id))
        response.raise_for_status()
        data = response.json()
    return data if isinstance(data, list) else []


async def build_arrival_board(station_id: str, line_id: str) -> ArrivalBoardResponse:
    station = get_station(station_id)
    line = get_line(line_id)
    if station is None:
        raise LookupError("Station not found")
    if line is None or line_id not in station.lines:
        raise ValueError("Line is not served by this station")

    arrivals = await fetch_line_arrivals(line_id)
    filtered = [
        arrival for arrival in arrivals
        if arrival.get("naptanId") == station_id and arrival.get("lineId") == line_id
    ]

    return ArrivalBoardResponse(
        station=public_station(station),
        line=line,
        boards=make_direction_boards(filtered),
    )


def make_direction_boards(arrivals: list[dict[str, Any]]) -> list[DirectionBoard]:
    grouped = defaultdict(dict)
    for arrival in arrivals:
        direction = platform_direction(arrival.get("platformName"))
        if direction is None:
            continue

        vehicle_id = normalized_text(arrival.get("vehicleId")) or normalized_text(arrival.get("id"))
        if not vehicle_id:
            continue

        destination = normalized_text(arrival.get("destinationName")) or "Unknown destination"
        seconds = safe_seconds(arrival.get("timeToStation"))
        key = (vehicle_id, destination)
        current = grouped[direction].get(key)

        if current is None:
            grouped[direction][key] = {
                "destination": destination,
                "seconds": seconds,
                "platforms": set(),
            }
        else:
            current["seconds"] = min(current["seconds"], seconds)

        platform = platform_number(arrival.get("platformName"))
        if platform:
            grouped[direction][key]["platforms"].add(platform)

    boards = []
    for direction in BOARD_DIRECTIONS:
        entries = sorted(grouped[direction].values(), key=lambda item: (item["seconds"], item["destination"]))
        boards.append(DirectionBoard(direction=direction, arrivals=format_entries(entries)))
    return boards


def format_entries(entries: list[dict[str, Any]]) -> list[ArrivalEntry]:
    return [
        ArrivalEntry(
            index=index,
            destinationName=entry["destination"],
            minutesText=minutes_text(entry["seconds"]),
            platformNumbers=format_platforms(entry["platforms"]),
            secondsToStation=entry["seconds"],
        )
        for index, entry in enumerate(entries, start=1)
    ]


def platform_direction(platform_name: Any) -> str | None:
    text = normalized_text(platform_name)
    if not text:
        return None

    lowered = text.casefold()
    for direction in BOARD_DIRECTIONS:
        if direction.casefold() in lowered:
            return direction
    return None


def platform_number(platform_name: Any) -> str | None:
    text = normalized_text(platform_name)
    if not text:
        return None

    match = PLATFORM_RE.search(text)
    return match.group(1) if match else None


def minutes_text(seconds: int) -> str:
    if seconds < 30:
        return "Due"
    minutes = max(1, round(seconds / 60))
    return f"{minutes} min"


def format_platforms(platforms: set[str]) -> str:
    if not platforms:
        return "-"
    return ",".join(sorted(platforms, key=platform_sort_key))


def platform_sort_key(platform: str) -> tuple[int, int | str]:
    return (0, int(platform)) if platform.isdigit() else (1, platform)


def safe_seconds(value: Any) -> int:
    try:
        return max(0, int(value))
    except (TypeError, ValueError):
        return 0


def normalized_text(value: Any) -> str:
    return str(value).strip() if value is not None else ""

from pathlib import Path

import httpx
from fastapi import FastAPI, HTTPException, Query
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles

from arrivals import build_arrival_board
from data_loader import get_station, public_station, search_stations
from models import ArrivalBoardResponse, StationSearchResult


APP_DIR = Path(__file__).resolve().parent
FRONTEND_DIST = APP_DIR / "frontend" / "dist"

app = FastAPI(title="Tube Arrivals")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["GET"],
    allow_headers=["*"],
)


@app.get("/api/stations/search", response_model=list[StationSearchResult])
def station_search(q: str = Query(..., min_length=1)) -> list[StationSearchResult]:
    return search_stations(q)


@app.get("/api/stations/{station_id}", response_model=StationSearchResult)
def station_detail(station_id: str) -> StationSearchResult:
    station = get_station(station_id)
    if station is None:
        raise HTTPException(status_code=404, detail="Station not found")
    return public_station(station)


@app.get("/api/stations/{station_id}/lines/{line_id}/arrivals", response_model=ArrivalBoardResponse)
async def station_arrivals(station_id: str, line_id: str) -> ArrivalBoardResponse:
    try:
        return await build_arrival_board(station_id, line_id)
    except LookupError as error:
        raise HTTPException(status_code=404, detail=str(error)) from error
    except ValueError as error:
        raise HTTPException(status_code=400, detail=str(error)) from error
    except httpx.HTTPStatusError as error:
        raise HTTPException(status_code=502, detail=f"TfL API returned {error.response.status_code}") from error
    except httpx.HTTPError as error:
        raise HTTPException(status_code=502, detail="Unable to reach TfL API") from error


if FRONTEND_DIST.exists():
    app.mount("/assets", StaticFiles(directory=FRONTEND_DIST / "assets"), name="assets")


@app.get("/{path:path}", include_in_schema=False)
def frontend(path: str) -> FileResponse:
    index_file = FRONTEND_DIST / "index.html"
    if index_file.exists():
        return FileResponse(index_file)
    raise HTTPException(status_code=404, detail="Frontend has not been built")
